inline std::string Lower(std::string_view value) {
    std::string s(value); for (char& c : s) if (c >= 'A' && c <= 'Z') c += 'a' - 'A'; return s;
}
inline const Item* Find(std::string_view id) {
    const auto key = Lower(id);
    auto at = std::lower_bound(Items.begin(), Items.end(), key, [](const Item& item, const std::string& value) { return Lower(item.id) < value; });
    return at != Items.end() && Lower(at->id) == key ? &*at : nullptr;
}
